nta.declaration:
//
// ===== GAME CONSTANTS =====
//
const int NUM_ENEMIES = 6;           // 3 Circles + 3 Squares
const int TIMEOUT = 100;             // Game timeout in time units

//
// ===== ENEMY PARAMETERS =====
//
const int CIRCLE_SPEED  = 1;         // Circle movement speed
const int CIRCLE_HEALTH = 10;        // Circle health points
const int CIRCLE_DAMAGE = 2;         // Circle damage to main tower
const int SQUARE_SPEED  = 3;         // Square movement speed
const int SQUARE_HEALTH = 20;        // Square health points
const int SQUARE_DAMAGE = 4;         // Square damage to main tower

//
// ===== SPAWN TIMING =====
// Enemy 0,1,2 are Circles: spawn at 0,2,4
// Enemy 3,4,5 are Squares: spawn at 0,3,6
//
const int spawn_times[NUM_ENEMIES] = {0, 2, 4, 0, 3, 6};

//
// ===== MAIN TOWER =====
//
const int MAIN_TOWER_HEALTH = 10;
int lives = MAIN_TOWER_HEALTH;

//
// ===== MAP CONSTANTS =====
//
const int MAP_WIDTH  = 16;
const int MAP_HEIGHT = 8;

//
// ===== MAIN PATH DEFINITION =====
// Path from (0,0) to (15,4)
const int PATH_LENGTH = 23;
const int main_path_x[PATH_LENGTH] = {
   0,  1,  2,  3,  4,
   4,  4,  4,  4,  5,
   6,  7,  8,  8,  8,
   9, 10, 11, 12, 13,
  14, 15, 15
};
const int main_path_y[PATH_LENGTH] = {
   0,  0,  0,  0,  0,
   1,  2,  3,  4,  4,
   4,  4,  4,  5,  6,
   7,  7,  7,  7,  7,
   7,  4,  4
};

//
// ===== BRANCH POINTS =====
//
const int NUM_BRANCHES = 2;
const int branch_x[NUM_BRANCHES] = {7, 10};
const int branch_y[NUM_BRANCHES] = {4, 7};

//
// ===== ALT PATH 1 =====
// from (7,4) going up then right
const int ALT_PATH1_LENGTH = 10;
const int alt1_x[ALT_PATH1_LENGTH] = {
   7, 7, 7, 8,  9, 10, 11, 12, 13, 14
};
const int alt1_y[ALT_PATH1_LENGTH] = {
   3,  2,  1, 1,  1,  1,  1,  1,  1,  1
};

//
// ===== ALT PATH 2 =====
// from (10,7) going up then right
const int ALT_PATH2_LENGTH = 5;
const int alt2_x[ALT_PATH2_LENGTH] = {
  10, 10, 11, 12, 13
};
const int alt2_y[ALT_PATH2_LENGTH] = {
   6,  5,  5,  5,  5
};

//
// ===== GAME STATE VARIABLES =====
//
int global_clock = 0;             // Global game time
bool game_over   = false;         // Game termination flag
bool timeout_reached = false;     // Timeout flag

//
// ===== ENEMY STATE ARRAYS =====
//
int enemy_health[NUM_ENEMIES];        // Current health
int enemy_damage[NUM_ENEMIES];        // Damage to tower
int enemy_position[NUM_ENEMIES];      // Index into main_path_x/y
int enemy_alt_position[NUM_ENEMIES];  // Index into alt1_x/y or alt2_x/y
int enemy_path_choice[NUM_ENEMIES];   // 0 = main, 1 = alt1, 2 = alt2
int enemy_spawn_time[NUM_ENEMIES];    // When each enemy spawns
bool enemy_spawned[NUM_ENEMIES];      // Has enemy spawned?
bool enemy_alive[NUM_ENEMIES];        // True iff alive on map
int enemy_time_on_map[NUM_ENEMIES];   // How many “move steps” taken

//
// ===== INITIALIZATION FUNCTION =====
//
void init_game() {
    int i;
    lives = MAIN_TOWER_HEALTH;
    global_clock = 0;
    game_over = false;
    timeout_reached = false;

    for (i = 0; i < NUM_ENEMIES; i++) {
        // Set health & damage based on type
        if (i < 3) {
            enemy_health[i] = CIRCLE_HEALTH;
            enemy_damage[i] = CIRCLE_DAMAGE;
        } else {
            enemy_health[i] = SQUARE_HEALTH;
            enemy_damage[i] = SQUARE_DAMAGE;
        }

        enemy_spawn_time[i]     = spawn_times[i];
        enemy_position[i]       = -1;  // not on main path yet
        enemy_alt_position[i]   = -1;  // not on alt path yet
        enemy_path_choice[i]    = 0;   // start “technically” on main
        enemy_spawned[i]        = false;
        enemy_alive[i]          = true;
        enemy_time_on_map[i]    = 0;
    }
}

//
// ===== HELPER FUNCTIONS =====
// Each function must explicitly return a value on every path,
// and avoid any C-loops (for/while). We use simple if/else.
//

// 1) Get speed of enemy i (Circles: 0–2; Squares: 3–5)
int get_enemy_speed(int i) {
    if (i < 3) return CIRCLE_SPEED;
    else        return SQUARE_SPEED;
}

// 2) Check if (x,y) is one of the branch_points
bool is_branch_point(int x, int y) {
    if (branch_x[0] == x && branch_y[0] == y) return true;
    if (branch_x[1] == x && branch_y[1] == y) return true;
    return false;
}

// 3) Get (x,y) of enemy i’s current position
// We cannot “return a struct,” so we provide two separate functions:
int get_enemy_x(int i) {
    if (!enemy_alive[i] || !enemy_spawned[i]) {
        return -1;
    }
    if (enemy_path_choice[i] == 0) {
        int idx = enemy_position[i];
        if (idx >= 0 && idx < PATH_LENGTH) {
            return main_path_x[idx];
        } else {
            return -1;
        }
    }
    else if (enemy_path_choice[i] == 1) {
        int idx = enemy_alt_position[i];
        if (idx >= 0 && idx < ALT_PATH1_LENGTH) {
            return alt1_x[idx];
        } else {
            return -1;
        }
    }
    else { // choice == 2
        int idx = enemy_alt_position[i];
        if (idx >= 0 && idx < ALT_PATH2_LENGTH) {
            return alt2_x[idx];
        } else {
            return -1;
        }
    }
}

int get_enemy_y(int i) {
    if (!enemy_alive[i] || !enemy_spawned[i]) {
        return -1;
    }
    if (enemy_path_choice[i] == 0) {
        int idx = enemy_position[i];
        if (idx >= 0 && idx < PATH_LENGTH) {
            return main_path_y[idx];
        } else {
            return -1;
        }
    }
    else if (enemy_path_choice[i] == 1) {
        int idx = enemy_alt_position[i];
        if (idx >= 0 && idx < ALT_PATH1_LENGTH) {
            return alt1_y[idx];
        } else {
            return -1;
        }
    }
    else {
        int idx = enemy_alt_position[i];
        if (idx >= 0 && idx < ALT_PATH2_LENGTH) {
            return alt2_y[idx];
        } else {
            return -1;
        }
    }
}

// 4) True if enemy i stands on a branch point
bool enemy_at_branch(int i) {
    if (!enemy_alive[i] || !enemy_spawned[i]) {
        return false;
    }
    int ex = get_enemy_x(i);
    int ey = get_enemy_y(i);
    return is_branch_point(ex, ey);
}

// 5) True if enemy i has reached the main tower at (15,4)
bool enemy_reached_goal(int i) {
    if (!enemy_alive[i] || !enemy_spawned[i]) {
        return false;
    }
    int ex = get_enemy_x(i);
    int ey = get_enemy_y(i);
    if (ex == 15 && ey == 4) return true;
    else                     return false;
}

// 6) True if enemy i can still move forward on whatever path it's on
bool can_move_forward(int i) {
    if (!enemy_alive[i] || !enemy_spawned[i]) {
        return false;
    }
    // If at a branch, must choose next path instead of moving
    if (enemy_at_branch(i)) {
        return false;
    }
    // If already at the goal coordinate, cannot move further
    if (enemy_reached_goal(i)) {
        return false;
    }
    // Now check “end of path” by index:
    if (enemy_path_choice[i] == 0) {
        return (enemy_position[i] < PATH_LENGTH - 1);
    }
    else if (enemy_path_choice[i] == 1) {
        return (enemy_alt_position[i] < ALT_PATH1_LENGTH - 1);
    }
    else { // choice == 2
        return (enemy_alt_position[i] < ALT_PATH2_LENGTH - 1);
    }
}

// 7) Advance enemy i one step forward on its chosen path
void move_enemy_forward(int i) {
    if (enemy_path_choice[i] == 0) {
        enemy_position[i] = enemy_position[i] + 1;
    }
    else if (enemy_path_choice[i] == 1) {
        enemy_alt_position[i] = enemy_alt_position[i] + 1;
    }
    else { // choice == 2
        enemy_alt_position[i] = enemy_alt_position[i] + 1;
    }
    enemy_time_on_map[i] = enemy_time_on_map[i] + 1;
}

// 8) Let enemy i “die” (either HP ≤ 0 or reached goal)
void remove_enemy_from_map(int i) {
    enemy_position[i]     = -1;
    enemy_alt_position[i] = -1;
    enemy_spawned[i]      = false;
    enemy_alive[i]        = false;
}

// 9) True if all spawned enemies are gone (dead or off‐map)
bool all_enemies_gone() {
    int i;
    for (i = 0; i < NUM_ENEMIES; i++) {
        if (enemy_spawned[i] && enemy_alive[i]) {
            // If they still occupy a valid index, they’re on the map
            if (enemy_path_choice[i] == 0) {
                if (enemy_position[i] >= 0 && enemy_position[i] < PATH_LENGTH)
                    return false;
            }
            else if (enemy_path_choice[i] == 1) {
                if (enemy_alt_position[i] >= 0 && enemy_alt_position[i] < ALT_PATH1_LENGTH)
                    return false;
            }
            else { // choice == 2
                if (enemy_alt_position[i] >= 0 && enemy_alt_position[i] < ALT_PATH2_LENGTH)
                    return false;
            }
        }
    }
    return true;
}

// 10) True if enemy i is “on a valid path index” (no out‐of‐bounds)
bool enemy_on_valid_path(int i) {
    if (!enemy_spawned[i] || !enemy_alive[i]) {
        return true;  // off‐map or dead is ok
    }
    if (enemy_path_choice[i] == 0) {
        if (enemy_position[i] >= 0 && enemy_position[i] < PATH_LENGTH)
            return true;
        else
            return false;
    }
    else if (enemy_path_choice[i] == 1) {
        if (enemy_alt_position[i] >= 0 && enemy_alt_position[i] < ALT_PATH1_LENGTH)
            return true;
        else
            return false;
    }
    else { // choice == 2
        if (enemy_alt_position[i] >= 0 && enemy_alt_position[i] < ALT_PATH2_LENGTH)
            return true;
        else
            return false;
    }
}

nta.system:
// Initialize game state
init_game();

// Instantiate system components
clock = GameClock();
gameManager = GameManager();

// Create all 6 enemies (0-2 Circles, 3-5 Squares)
enemy0 = Enemy(0);
enemy1 = Enemy(1);  
enemy2 = Enemy(2);
enemy3 = Enemy(3);
enemy4 = Enemy(4);
enemy5 = Enemy(5);

// System composition
system clock, gameManager, enemy0, enemy1, enemy2, enemy3, enemy4, enemy5;
